```typescript
type MemberCheck =
  | { status: "active"; memberId: string; name?: string; expiresAt?: string }
  | { status: "not_found" }
  | { status: "inactive"; reason?: string }   // found, but expired/frozen
  | { status: "unreachable" };                // timeout, network error, or 5xx

const API_BASE = "https://your-gym-server.example.com/api";
const TIMEOUT_MS = 2000; // keep short so the door doesn't feel stuck

async function checkMemberOnServer(
  memberId: string,
  deviceToken: string
): Promise<MemberCheck> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), TIMEOUT_MS);

  try {
    const res = await fetch(
      `${API_BASE}/members/${encodeURIComponent(memberId)}/access`,
      {
        method: "GET",
        headers: {
          Authorization: `Bearer ${deviceToken}`,
          Accept: "application/json",
        },
        signal: controller.signal,
      }
    );

    if (res.status === 404) return { status: "not_found" };
    if (!res.ok) return { status: "unreachable" }; // 5xx, 401, etc.

    const data = await res.json();
    // Assumed response: { active: boolean, name?, expiresAt?, reason? }
    return data.active
      ? { status: "active", memberId, name: data.name, expiresAt: data.expiresAt }
      : { status: "inactive", reason: data.reason };
  } catch {
    return { status: "unreachable" }; // timeout or no network
  } finally {
    clearTimeout(timer);
  }
}
```

