@Component
class DebugInProdCheck {
    private static final Logger log = LoggerFactory.getLogger(DebugInProdCheck.class);

    private final Environment env;
    private final LoggingSystem loggingSystem;

    DebugInProdCheck(Environment env, LoggingSystem loggingSystem) {
        this.env = env;
        this.loggingSystem = loggingSystem;
    }

