    void check() {
        if (!env.acceptsProfiles(Profiles.of("prod", "production"))) return;

        List<String> noisy = loggingSystem.getLoggerConfigurations().stream()
            .filter(c -> c.getConfiguredLevel() == LogLevel.DEBUG
                      || c.getConfiguredLevel() == LogLevel.TRACE)
            .map(c -> c.getName() + "=" + c.getConfiguredLevel())
            .toList();

        if (!noisy.isEmpty()) {
            log.warn("DEBUG/TRACE logging enabled in production for: {}. "
                   + "This increases log volume and vendor cost. Revert if not intentional.", noisy);
        }
    }
}
