## JavaScript

```js
class ExamCountdown {
  constructor({ examId, onTick, onExpire, resyncEveryMs = 5 * 60_000 }) {
    this.examId = examId;
    this.onTick = onTick;
    this.onExpire = onExpire;
    this.resyncEveryMs = resyncEveryMs;

    this.deadline = null;      // in performance.now() time
    this.expired = false;
    this.timeoutId = null;
    this.lastPerf = performance.now();
    this.lastWall = Date.now(); // used ONLY to detect sleep, never for the countdown
  }

  async start() {
    await this.sync(3);
    this.#tick();

    // Periodic resync
    setInterval(() => this.#safeSync(), this.resyncEveryMs);

    // Resync when the tab returns or the network comes back
    document.addEventListener('visibilitychange', () => {
      if (document.visibilityState === 'visible') this.#safeSync();
    });
    window.addEventListener('online', () => this.#safeSync());
  }

  // Take several samples and keep the one with the lowest round-trip time,
  // since it has the smallest uncertainty about transit delay.
  async sync(samples = 1) {
    let best = null;
    for (let i = 0; i < samples; i++) {
      const t0 = performance.now();
      const res = await fetch(`/api/exams/${this.examId}/clock`, { cache: 'no-store' });
      if (!res.ok) throw new Error(`clock fetch failed: ${res.status}`);
      const data = await res.json();
      const t1 = performance.now();

      const rtt = t1 - t0;
      if (!best || rtt < best.rtt) {
        // Server computed remainingMs about when it sent the response,
        // so about half the round trip has elapsed since then.
        best = { rtt, deadline: t1 + (data.remainingMs - rtt / 2) };
      }
    }
    this.deadline = best.deadline;
  }

  async #safeSync(samples = 1) {
    try {
      await this.sync(samples);
      this.#setWarning(false);
    } catch {
      // Keep counting down from the last known deadline and retry shortly.
      this.#setWarning(true);
      setTimeout(() => this.#safeSync(), 15_000);
    }
  }

  #tick = async () => {
    const nowPerf = performance.now();
    const nowWall = Date.now();

    // If the wall clock and the monotonic clock disagree, the machine
    // probably slept or the clock was changed. Resync to be safe.
    const drift = (nowWall - this.lastWall) - (nowPerf - this.lastPerf);
    this.lastPerf = nowPerf;
    this.lastWall = nowWall;
    if (Math.abs(drift) > 2000) await this.#safeSync();

    const remaining = this.deadline - performance.now();

    if (remaining <= 0 && !this.expired) {
      // Confirm with the server in case time was extended (accommodations).
      await this.#safeSync();
      if (this.deadline - performance.now() <= 0) {
        this.expired = true;
        this.onTick(0);
        this.onExpire();
        return;
      }
    }

    this.onTick(Math.max(0, this.deadline - performance.now()));
    // Wake slightly more often than once a second so the display doesn't skip digits.
    this.timeoutId = setTimeout(this.#tick, 250);
  };

  #setWarning(show) {
    const el = document.getElementById('timer-warning');
    if (el) el.hidden = !show;
  }
}
```

