Here's a countdown class that anchors to the server's remaining time and measures elapsed time with `performance.now()`. It never reads `Date.now()`, so the device clock can't affect it.

```ts
type TimeResponse = { serverTime: number; endsAt: number; remainingMs: number };

export class ExamCountdown {
  private anchorPerf = 0;          // performance.now() when the anchor was set
  private remainingAtAnchor = 0;   // ms left at that moment, per the server
  private tickTimer?: number;
  private syncTimer?: number;
  private finished = false;

  constructor(
    private examId: string,
    private onTick: (remainingMs: number) => void,
    private onExpire: () => void,
    private resyncEveryMs = 60_000,
  ) {}

  async start() {
    await this.sync("POST", "start", true); // throws if the exam can't be started
    this.tick();

    this.syncTimer = window.setInterval(() => this.safeResync(), this.resyncEveryMs);
    document.addEventListener("visibilitychange", this.onVisibility);
    window.addEventListener("online", this.safeResync);
  }

  stop() {
    this.finished = true;
    clearTimeout(this.tickTimer);
    clearInterval(this.syncTimer);
    document.removeEventListener("visibilitychange", this.onVisibility);
    window.removeEventListener("online", this.safeResync);
  }

  remainingMs(): number {
    return Math.max(0, this.remainingAtAnchor - (performance.now() - this.anchorPerf));
  }

  // --- internals ---

  private async sync(method: "GET" | "POST", path: "start" | "time", force: boolean) {
    const t0 = performance.now();
    const res = await fetch(`/api/exams/${this.examId}/${path}`, {
      method,
      cache: "no-store",
      credentials: "same-origin",
    });
    if (!res.ok) throw new Error(`Time sync failed: ${res.status}`);
    const data: TimeResponse = await res.json();
    const t1 = performance.now();

    const rtt = t1 - t0;
    // A very slow round trip makes the estimate sloppy; keep the old anchor instead.
    if (!force && rtt > 3000) return;

    // Assume the response spent half the round trip in transit.
    this.remainingAtAnchor = Math.max(0, data.remainingMs - rtt / 2);
    this.anchorPerf = t1;
  }

  private safeResync = () => {
    if (this.finished) return;
    this.sync("GET", "time", false).catch(() => {
      /* offline or server hiccup: keep counting from the last anchor */
    });
  };

  private onVisibility = () => {
    if (document.visibilityState === "visible") this.safeResync();
  };

  private tick = () => {
    if (this.finished) return;
    const ms = this.remainingMs();
    this.onTick(ms);

    if (ms <= 0) {
      void this.handleZero();
      return;
    }
    // Wake just after the displayed second changes. Because we recompute from the
    // monotonic clock each time, throttled timers delay the display, not the value.
    const untilNextSecond = ms % 1000 || 1000;
    this.tickTimer = window.setTimeout(this.tick, untilNextSecond + 10);
  };

  private async handleZero() {
    // Confirm with the server before ending, in case this device's timers drifted.
    try {
      await this.sync("GET", "time", true);
    } catch {
      /* can't reach the server: fall through and expire */
    }
    if (this.remainingMs() > 0) {
      this.tick();
      return;
    }
    this.stop();
    this.onExpire(); // e.g. autosubmit; the server still makes the final call
  }
}
```

