Here's a countdown that uses the `/time` endpoint. It runs on a monotonic clock, re-syncs against the server, and treats the server's `remainingMs` as authoritative.

```ts
type TimerOptions = {
  examId: string;
  onTick: (remainingMs: number) => void;
  onExpire: () => void;
  resyncEveryMs?: number;
};

export function createExamCountdown(opts: TimerOptions) {
  const { examId, onTick, onExpire, resyncEveryMs = 2 * 60_000 } = opts;

  let deadline = 0;          // in performance.now() units
  let tickHandle: number | undefined;
  let syncHandle: number | undefined;
  let expired = false;
  let stopped = false;

  async function sync() {
    try {
      const t0 = performance.now();
      const r = await fetch(`/api/exams/${examId}/time`, { cache: "no-store" });
      if (!r.ok) throw new Error(`sync failed: ${r.status}`);
      const data: { remainingMs: number } = await r.json();
      const rtt = performance.now() - t0;

      // The server computed remainingMs about rtt/2 before we received it.
      deadline = performance.now() + data.remainingMs - rtt / 2;
    } catch {
      // Network hiccup: keep counting down against the last known deadline.
      // The next sync will correct it.
    }
  }

  function tick() {
    if (stopped || expired) return;
    const remaining = Math.max(0, deadline - performance.now());
    onTick(remaining);
    if (remaining === 0) {
      expired = true;
      stop();
      onExpire();
    }
  }

  function onVisibility() {
    if (document.visibilityState === "visible") void sync();
  }

  async function start() {
    await sync();
    tick();
    tickHandle = window.setInterval(tick, 250);
    syncHandle = window.setInterval(sync, resyncEveryMs);
    document.addEventListener("visibilitychange", onVisibility);
    window.addEventListener("online", sync);
  }

  function stop() {
    stopped = true;
    clearInterval(tickHandle);
    clearInterval(syncHandle);
    document.removeEventListener("visibilitychange", onVisibility);
    window.removeEventListener("online", sync);
  }

  return { start, stop, syncNow: sync };
}
