Here's a React hook (TypeScript) that uses the `/clock` endpoint from before. It never reads `Date.now()` for the countdown. It uses only the server's `remainingMs` and `performance.now()`.

```tsx
import { useEffect, useRef, useState } from "react";

type Sync = {
  remainingAtSync: number; // ms left, as of `syncedAt`
  syncedAt: number;        // performance.now() value when that was true
  rtt: number;
};

async function sampleClock(examId: string): Promise<Sync> {
  const t0 = performance.now();
  const res = await fetch(`/api/exams/${examId}/clock`, {
    cache: "no-store",
    credentials: "include",
  });
  const t1 = performance.now();
  if (!res.ok) throw new Error(`clock sync failed: ${res.status}`);
  const { remainingMs } = await res.json();
  const rtt = t1 - t0;
  return {
    // Assume the server read its clock halfway through the round trip.
    remainingAtSync: remainingMs - rtt / 2,
    syncedAt: t1,
    rtt,
  };
}

// Take a few samples and keep the one with the lowest round-trip time,
// since that one has the smallest possible error.
async function bestSample(examId: string, n: number): Promise<Sync> {
  let best: Sync | null = null;
  for (let i = 0; i < n; i++) {
    try {
      const s = await sampleClock(examId);
      if (!best || s.rtt < best.rtt) best = s;
    } catch (e) {
      if (i === n - 1 && !best) throw e;
    }
  }
  if (!best) throw new Error("no clock samples");
  return best;
}

export function useExamCountdown(examId: string, onExpire: () => void) {
  const [remainingMs, setRemainingMs] = useState<number | null>(null);
  const [expired, setExpired] = useState(false);
  const [syncError, setSyncError] = useState(false);

  const syncRef = useRef<Sync | null>(null);
  const onExpireRef = useRef(onExpire);
  onExpireRef.current = onExpire;

  useEffect(() => {
    let cancelled = false;
    let finished = false;
    let confirming = false;

    const remaining = () => {
      const s = syncRef.current;
      if (!s) return null;
      return Math.max(0, s.remainingAtSync - (performance.now() - s.syncedAt));
    };

    const resync = async (samples = 1) => {
      try {
        const s = await bestSample(examId, samples);
        if (cancelled) return;
        syncRef.current = s; // server is authoritative, so jumps either way are fine
        setSyncError(false);
      } catch {
        // Keep counting from the last good sync; don't stop the timer.
        if (!cancelled) setSyncError(true);
      }
    };

    const tick = async () => {
      if (finished) return;
      const r = remaining();
      if (r === null) return;
      setRemainingMs(r);

      if (r <= 0 && !confirming) {
        // Local timer hit zero. Confirm with the server first, in case the
        // student was granted extra time or we drifted.
        confirming = true;
        await resync();
        confirming = false;
        if (cancelled || finished) return;
        if ((remaining() ?? 0) <= 0) {
          finished = true;
          setRemainingMs(0);
          setExpired(true);
          onExpireRef.current();
        }
      }
    };

    // Initial sync (3 samples), then start ticking.
    resync(3).then(tick);

    // Tick often, but compute from the monotonic clock rather than
    // decrementing a counter, so throttled timers don't cause drift.
    const tickId = setInterval(tick, 250);

    // Periodic re-sync.
    const syncId = setInterval(() => resync(), 2 * 60_000);

    // Re-sync when the tab returns or the network comes back. This covers
    // laptop sleep, where performance.now() may have paused.
    const onVisible = () => {
      if (document.visibilityState === "visible") resync(2).then(tick);
    };
    const onOnline = () => resync().then(tick);
    document.addEventListener("visibilitychange", onVisible);
    window.addEventListener("online", onOnline);

    return () => {
      cancelled = true;
      clearInterval(tickId);
      clearInterval(syncId);
      document.removeEventListener("visibilitychange", onVisible);
      window.removeEventListener("online", onOnline);
    };
  }, [examId]);

  return { remainingMs, expired, syncError };
}
```

**Using it**

```tsx
function formatMs(ms: number) {
  const total = Math.ceil(ms / 1000);
  const h = Math.floor(total / 3600);
  const m = Math.floor((total % 3600) / 60);
  const s = total % 60;
  const mm = String(m).padStart(2, "0");
  const ss = String(s).padStart(2, "0");
  return h > 0 ? `${h}:${mm}:${ss}` : `${mm}:${ss}`;
}

export function ExamTimer({ examId, submitExam }: {
  examId: string;
  submitExam: () => void;
}) {
  const { remainingMs, expired, syncError } = useExamCountdown(examId, submitExam);

  if (remainingMs === null) return <span>Syncing clock…</span>;

  return (
    <div>
      <span role="timer" aria-live="off">{formatMs(remainingMs)}</span>
      {syncError && !expired && (
        <small> Connection issue. Timer may be slightly off, but your time is still being tracked.</small>
      )}
      {expired && <strong> Time's up. Submitting…</strong>}
    </div>
  );
}
```

**Design notes**

- **Why confirm at zero:** the final sync before auto-submitting means a student with extra time, or one whose timer drifted, isn't cut off early. If that request fails, it falls back to the local timer and submits.
- **Why `Math.ceil` in the display:** the timer shows `00:01` until time is actually up, rather than showing `00:00` while a fraction of a second remains.
- **Accessibility:** `aria-live="off"` keeps screen readers from announcing every second. Add a separate live region that announces at milestones (10 minutes, 5 minutes, 1 minute left).
- **Server remains the judge:** if the auto-submit request fails (connection drop, tab closed), the server should still apply its own deadline check to the last autosaved answers. Otherwise a lost request becomes a missing submission.

