        "SELECT COUNT(*)::int AS count, COALESCE(MAX(position), -1) AS max_pos FROM listing_photos WHERE listing_id = $1",
        [listingId]);
      if (count + req.files.length > MAX_PHOTOS_PER_LISTING) {
        return res.status(400).json({
          error: `Max ${MAX_PHOTOS_PER_LISTING} photos per listing (${count} already uploaded)`,
        });
      }

      // Validate + process every file before uploading anything
      const processed = [];
      for (const file of req.files) {
        const img = sharp(file.buffer, { limitInputPixels: 50_000_000 }); // decompression-bomb guard
