        } catch {
          return res.status(400).json({ error: `${file.originalname}: not a valid image` });
        }
        if (!ALLOWED_FORMATS.has(meta.format)) {
          return res.status(400).json({ error: `${file.originalname}: only JPEG, PNG, or WebP allowed` });
        }

        // rotate() applies EXIF orientation; re-encoding drops all metadata (incl. GPS)
        const full = await sharp(file.buffer, { limitInputPixels: 50_000_000 })
          .rotate()
          .resize({ width: 2048, height: 2048, fit: "inside", withoutEnlargement: true })
          .webp({ quality: 82 })
          .toBuffer({ resolveWithObject: true });

        const thumb = await sharp(file.buffer, { limitInputPixels: 50_000_000 })
          .rotate()
          .resize({ width: 400, height: 400, fit: "cover" })
          .webp({ quality: 75 })
          .toBuffer();

        processed.push({ full, thumb });
      }

      // Upload to object storage
      const photos = [];
      for (const { full, thumb } of processed) {
        const id = randomUUID();
        const key = `listings/${listingId}/${id}.webp`;
        const thumbKey = `listings/${listingId}/${id}_thumb.webp`;

        const put = (Key, Body) =>
          s3.send(new PutObjectCommand({
            Bucket: BUCKET, Key, Body,
            ContentType: "image/webp",
            CacheControl: "public, max-age=31536000, immutable",
          }));

        await put(key, full.data);        uploadedKeys.push(key);
        await put(thumbKey, thumb);       uploadedKeys.push(thumbKey);

        photos.push({ id, key, thumbKey, width: full.info.width, height: full.info.height });
      }

      // Persist metadata
      const client = await db.connect();
      try {
        await client.query("BEGIN");
        let pos = max_pos + 1;
        for (const p of photos) {
          await client.query(
            `INSERT INTO listing_photos (id, listing_id, key, thumb_key, width, height, position)
             VALUES ($1,$2,$3,$4,$5,$6,$7)`,
            [p.id, listingId, p.key, p.thumbKey, p.width, p.height, pos++]);
        }
        await client.query("COMMIT");
      } catch (e) {
        await client.query("ROLLBACK");
        throw e;
      } finally {
        client.release();
      }

      res.status(201).json({
        photos: photos.map((p) => ({
          id: p.id,
          url: `${PUBLIC_BASE_URL}/${p.key}`,
          thumbUrl: `${PUBLIC_BASE_URL}/${p.thumbKey}`,
          width: p.width,
          height: p.height,
        })),
      });
    } catch (err) {
      // Don't leave orphaned objects if anything failed after uploading
      if (uploadedKeys.length) {
        s3.send(new DeleteObjectsCommand({
          Bucket: BUCKET,
          Delete: { Objects: uploadedKeys.map((Key) => ({ Key })) },
        })).catch(() => {});
      }
      next(err);
    }
  }
);

// Translate multer errors into clean 4xx responses
router.use((err, req, res, next) => {
  if (err instanceof multer.MulterError) {
    const msg = err.code === "LIMIT_FILE_SIZE"
      ? `Each file must be under ${MAX_FILE_BYTES / 1024 / 1024} MB`
      : err.message;
    return res.status(400).json({ error: msg });
  }
  next(err);
});

export default router;
```

## Design choices

- **Validation by content, not by header.** `Content-Type` and file extensions are client-controlled, so sharp decoding the file is the check.
- **Re-encoding strips EXIF.** Phone photos often embed GPS coordinates, which is a real privacy problem on a classifieds site where people photograph items at home. Re-encoding also neutralizes most malicious payloads hidden in image files.
- **Server-generated keys.** Keys are never derived from the user's filename, which avoids path tricks and collisions.
- **Immutable cache headers.** Keys are unique per upload, so the CDN can cache them forever.
- **Cleanup on failure.** If the DB write fails, the uploaded objects are deleted.

## Things to decide

1. **Bucket access.** I assumed public reads through a CDN, which is simplest for listing pages. If you'd rather keep the bucket private, serve through signed URLs or a CDN origin-access policy.
2. **Scale.** Buffering uploads through your app server is fine at modest volume. If it grows, switch to presigned direct-to-S3 uploads with a processing step (e.g. a Lambda) afterward.
3. **Moderation.** Classifieds sites attract spam and abusive images. You may want to hook in an image-moderation API after the upload step.
4. **Rate limiting.** Add per-user limits to this route.
5. **Photo limit race.** Two simultaneous requests could slip past the count check. If that matters, lock the listing row (`SELECT ... FOR UPDATE`) inside the transaction.

