```js
// routes/listingPhotos.js
import express from 'express';
import multer from 'multer';
import sharp from 'sharp';
import crypto from 'node:crypto';
import { S3Client, PutObjectCommand, DeleteObjectsCommand } from '@aws-sdk/client-s3';
import { db } from '../db.js';                 // your DB client (pg-style)
import { requireAuth } from '../middleware/auth.js';

const router = express.Router();

const s3 = new S3Client({ region: process.env.S3_REGION /*, endpoint for R2/MinIO/etc. */ });
const BUCKET = process.env.S3_BUCKET;
const PUBLIC_BASE_URL = process.env.PHOTO_BASE_URL; // CDN or bucket URL

const MAX_FILE_BYTES = 10 * 1024 * 1024; // 10 MB per file
const MAX_FILES_PER_REQUEST = 5;
const MAX_PHOTOS_PER_LISTING = 10;

const upload = multer({
  storage: multer.memoryStorage(),
  limits: { fileSize: MAX_FILE_BYTES, files: MAX_FILES_PER_REQUEST },
});

// Re-encode everything: validates it's a real image, strips EXIF (incl. GPS), normalizes format.
async function processImage(buffer) {
  const base = () =>
    sharp(buffer, { limitInputPixels: 40_000_000 }) // guard against decompression bombs
      .rotate(); // apply EXIF orientation before metadata is stripped

  const [full, thumb] = await Promise.all([
    base().resize({ width: 2048, height: 2048, fit: 'inside', withoutEnlargement: true })
          .webp({ quality: 82 }).toBuffer({ resolveWithObject: true }),
    base().resize({ width: 400, height: 400, fit: 'cover' })
          .webp({ quality: 75 }).toBuffer(),
  ]);

  return { full: full.data, width: full.info.width, height: full.info.height, thumb };
}

function putObject(key, body) {
  return s3.send(new PutObjectCommand({
    Bucket: BUCKET,
    Key: key,
    Body: body,
    ContentType: 'image/webp',
    CacheControl: 'public, max-age=31536000, immutable',
  }));
}

router.post(
  '/api/listings/:listingId/photos',
  requireAuth,
  upload.array('photos', MAX_FILES_PER_REQUEST),
  async (req, res) => {
    const { listingId } = req.params;
    const files = req.files ?? [];
    if (files.length === 0) return res.status(400).json({ error: 'No files uploaded' });

    // Ownership check
    const { rows: [listing] } = await db.query(
      'SELECT id, user_id FROM listings WHERE id = $1', [listingId]);
    if (!listing) return res.status(404).json({ error: 'Listing not found' });
    if (listing.user_id !== req.user.id) return res.status(403).json({ error: 'Forbidden' });

    // Photo cap
    const { rows: [{ count }] } = await db.query(
      'SELECT COUNT(*)::int AS count FROM listing_photos WHERE listing_id = $1', [listingId]);
    if (count + files.length > MAX_PHOTOS_PER_LISTING) {
      return res.status(409).json({
        error: `Listings can have at most ${MAX_PHOTOS_PER_LISTING} photos (currently ${count})`,
      });
    }

    const uploadedKeys = [];
    try {
      // Process first so we fail before writing anything if any file is bad
      const processed = [];
      for (const file of files) {
        try {
          processed.push(await processImage(file.buffer));
        } catch {
          return res.status(415).json({ error: `"${file.originalname}" is not a valid image` });
        }
      }

      const saved = [];
      for (const [i, img] of processed.entries()) {
        const id = crypto.randomUUID();
        const key = `listings/${listingId}/${id}.webp`;
        const thumbKey = `listings/${listingId}/${id}_thumb.webp`;

        await Promise.all([putObject(key, img.full), putObject(thumbKey, img.thumb)]);
        uploadedKeys.push(key, thumbKey);

        const { rows: [row] } = await db.query(
          `INSERT INTO listing_photos
             (id, listing_id, storage_key, thumb_key, width, height, position)
           VALUES ($1, $2, $3, $4, $5, $6,
             (SELECT COALESCE(MAX(position), -1) + 1 FROM listing_photos WHERE listing_id = $2))
           RETURNING id, position`,
          [id, listingId, key, thumbKey, img.width, img.height]);

        saved.push({
          id: row.id,
          position: row.position,
          url: `${PUBLIC_BASE_URL}/${key}`,
          thumbUrl: `${PUBLIC_BASE_URL}/${thumbKey}`,
          width: img.width,
          height: img.height,
        });
      }

      res.status(201).json({ photos: saved });
    } catch (err) {
      console.error('Photo upload failed', err);
      // Best-effort cleanup of orphaned objects
      if (uploadedKeys.length) {
        s3.send(new DeleteObjectsCommand({
          Bucket: BUCKET,
          Delete: { Objects: uploadedKeys.map((Key) => ({ Key })) },
        })).catch(() => {});
      }
      res.status(500).json({ error: 'Upload failed' });
    }
  }
);

// Multer errors (file too large, too many files)
router.use((err, req, res, next) => {
  if (err instanceof multer.MulterError) {
    const status = err.code === 'LIMIT_FILE_SIZE' ? 413 : 400;
    return res.status(status).json({ error: err.message });
  }
  next(err);
});

export default router;
```

