```ts
import Stripe from "stripe";

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY!);

type RefundReason = "duplicate" | "fraudulent" | "requested_by_customer";

interface CreateRefundParams {
  orderId: string;
  paymentIntentId: string;
  amountCents?: number;      // omit for a full refund
  reason?: RefundReason;
  adminUserId: string;       // who initiated it, for audit
  idempotencyKey: string;    // generated once per button click / refund attempt
}

export async function createRefund({
  orderId,
  paymentIntentId,
  amountCents,
  reason,
  adminUserId,
  idempotencyKey,
}: CreateRefundParams) {
  try {
    const refund = await stripe.refunds.create(
      {
        payment_intent: paymentIntentId,
        ...(amountCents !== undefined && { amount: amountCents }),
        ...(reason && { reason }),
        metadata: { order_id: orderId, refunded_by: adminUserId },
      },
      { idempotencyKey }
    );

    return { ok: true as const, refund };
  } catch (err) {
    if (err instanceof Stripe.errors.StripeError) {
      // e.g. charge_already_refunded, amount exceeds refundable balance
      return { ok: false as const, code: err.code, message: err.message };
    }
    throw err;
  }
}
```

A few things worth wiring up around it:

- **Call it from your backend only.** The button should hit your own endpoint, which checks the admin's permissions and then calls this. The secret key should never reach the browser.
- **Idempotency key:** generate it when the refund form is opened or submitted (e.g. a UUID stored with the pending refund), not on each retry. Otherwise a double-click or network retry can issue two refunds.
- **Validate the amount server-side.** Check that it's positive and doesn't exceed `amount_paid - already_refunded` for that order. Stripe will reject over-refunds, but you'll want a clearer error.
- **Don't treat the API response as the final state.** Refunds can be `pending` or later `failed`. Listen for the `refund.updated` and `refund.failed` webhooks (or `charge.refunded`) to update your order status.
- **Record it locally:** store the refund ID, amount, admin user, and reason in your DB alongside the order for audit and reconciliation.

