```ts
import { Router } from "express";
import { z } from "zod";
import { pool } from "./db";
import { createRefund } from "./stripe-refunds"; // the function from before

const router = Router();

const bodySchema = z.object({
  amountCents: z.number().int().positive().optional(), // omit = refund remaining balance
  reason: z.enum(["duplicate", "fraudulent", "requested_by_customer"]).optional(),
  idempotencyKey: z.string().uuid(),
});

router.post("/api/admin/orders/:orderId/refunds", requireAuth, async (req, res) => {
  const admin = req.user!;
  if (!admin.permissions.includes("orders:refund")) {
    return res.status(403).json({ error: "forbidden" });
  }

  const parsed = bodySchema.safeParse(req.body);
  if (!parsed.success) {
    return res.status(400).json({ error: "invalid_request", details: parsed.error.flatten() });
  }
  const { amountCents, reason, idempotencyKey } = parsed.data;
  const { orderId } = req.params;

  // Step 1: validate and reserve the amount in a transaction.
  const client = await pool.connect();
  let refundRow: { id: string; amount_cents: number; status: string; stripe_refund_id: string | null };
  let paymentIntentId: string;

  try {
    await client.query("BEGIN");

    // Lock the order row so concurrent refunds on the same order serialize.
    const orderRes = await client.query(
      `SELECT id, status, payment_intent_id, amount_paid_cents
         FROM orders WHERE id = $1 FOR UPDATE`,
      [orderId]
    );
    const order = orderRes.rows[0];
    if (!order) {
      await client.query("ROLLBACK");
      return res.status(404).json({ error: "order_not_found" });
    }
    if (!order.payment_intent_id) {
      await client.query("ROLLBACK");
      return res.status(409).json({ error: "order_not_refundable" });
    }
    paymentIntentId = order.payment_intent_id;

    // Replay of the same attempt? Reuse the existing row.
    const existing = await client.query(
      `SELECT id, amount_cents, status, stripe_refund_id
         FROM refunds WHERE idempotency_key = $1`,
      [idempotencyKey]
    );

    if (existing.rows[0]) {
      refundRow = existing.rows[0];
      await client.query("COMMIT");
      if (refundRow.status !== "requested") {
        // Already resolved, so just return the stored result.
        return res.status(200).json({ refund: refundRow });
      }
      // Still "requested": a previous attempt may have crashed mid-call.
      // Fall through and call Stripe again with the same key (safe).
    } else {
      const refundedRes = await client.query(
        `SELECT COALESCE(SUM(amount_cents), 0)::int AS refunded
           FROM refunds
          WHERE order_id = $1 AND status IN ('requested', 'pending', 'succeeded')`,
        [orderId]
      );
      const refundable = order.amount_paid_cents - refundedRes.rows[0].refunded;
      const amount = amountCents ?? refundable;

      if (amount <= 0 || amount > refundable) {
        await client.query("ROLLBACK");
        return res.status(422).json({ error: "invalid_amount", refundableCents: refundable });
      }

      const inserted = await client.query(
        `INSERT INTO refunds (order_id, amount_cents, reason, status, admin_user_id, idempotency_key)
         VALUES ($1, $2, $3, 'requested', $4, $5)
         RETURNING id, amount_cents, status, stripe_refund_id`,
        [orderId, amount, reason ?? null, admin.id, idempotencyKey]
      );
      refundRow = inserted.rows[0];
      await client.query("COMMIT");
    }
  } catch (err) {
    await client.query("ROLLBACK").catch(() => {});
    console.error("refund reservation failed", err);
    return res.status(500).json({ error: "internal_error" });
  } finally {
    client.release();
  }

  // Step 2: call the provider outside the transaction.
  try {
    const result = await createRefund({
      orderId,
      paymentIntentId,
      amountCents: refundRow.amount_cents, // always explicit, even for "full" refunds
      reason,
      adminUserId: admin.id,
      idempotencyKey,
    });

    if (!result.ok) {
      await pool.query(
        `UPDATE refunds SET status = 'failed', failure_code = $2, failure_message = $3 WHERE id = $1`,
        [refundRow.id, result.code ?? null, result.message]
      );
      return res.status(502).json({ error: "provider_rejected", code: result.code, message: result.message });
    }

    // Stripe status: pending | succeeded | failed | requires_action | canceled
    const updated = await pool.query(
      `UPDATE refunds SET status = $2, stripe_refund_id = $3 WHERE id = $1
       RETURNING id, amount_cents, status, stripe_refund_id`,
      [refundRow.id, result.refund.status, result.refund.id]
    );
    return res.status(201).json({ refund: updated.rows[0] });
  } catch (err) {
    // Outcome unknown (network/timeout). Leave the row as "requested".
    // Retrying with the same idempotency key is safe, and the webhook will reconcile.
    console.error("refund provider call failed", err);
    return res.status(504).json({ error: "provider_unreachable_retry_safe" });
  }
});

export default router;
```

