```ts
import Stripe from "stripe";

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY!);

interface RefundParams {
  orderId: string;
  paymentIntentId: string;   // stored on your order when it was paid
  amountCents?: number;      // omit for a full refund
  reason?: "duplicate" | "fraudulent" | "requested_by_customer";
  adminUserId: string;       // who clicked the button
}

export async function refundOrder(params: RefundParams) {
  const { orderId, paymentIntentId, amountCents, reason, adminUserId } = params;

  try {
    const refund = await stripe.refunds.create(
      {
        payment_intent: paymentIntentId,
        ...(amountCents !== undefined && { amount: amountCents }),
        ...(reason && { reason }),
        metadata: {
          order_id: orderId,
          refunded_by: adminUserId,
        },
      },
      {
        // Prevents double refunds on double-clicks or retries.
        // For partial refunds, include something that distinguishes
        // intentional separate refunds (e.g., a client-generated request ID).
        idempotencyKey: `refund:${orderId}:${amountCents ?? "full"}`,
      }
    );

    return { ok: true as const, refundId: refund.id, status: refund.status };
  } catch (err) {
    if (err instanceof Stripe.errors.StripeError) {
      // e.g. charge_already_refunded, amount exceeds the refundable balance
      return { ok: false as const, code: err.code, message: err.message };
    }
    throw err;
  }
}
```

