## 2. Server endpoint

```ts
import express from "express";
import { refundOrder } from "./refunds";

const router = express.Router();

router.post(
  "/admin/orders/:id/refund",
  requireAuth,
  requirePermission("refund:create"), // don't let every admin refund by default
  async (req, res) => {
    const { id } = req.params;
    const { amountCents, reason, requestId } = req.body ?? {};

    // --- Validate input ---
    if (typeof requestId !== "string" || requestId.length < 8) {
      return res.status(400).json({ error: "requestId is required" });
    }
    if (
      amountCents !== undefined &&
      (!Number.isInteger(amountCents) || amountCents <= 0)
    ) {
      return res.status(400).json({ error: "Invalid amount" });
    }
    if (
      reason !== undefined &&
      !["duplicate", "fraudulent", "requested_by_customer"].includes(reason)
    ) {
      return res.status(400).json({ error: "Invalid reason" });
    }

    // --- Load the order from YOUR db; never trust client-supplied payment data ---
    const order = await db.orders.findById(id);
    if (!order) return res.status(404).json({ error: "Order not found" });
    if (!order.paymentIntentId || order.status === "unpaid") {
      return res.status(409).json({ error: "Order has no captured payment" });
    }

    const refundable = order.totalCents - order.refundedCents;
    if (refundable <= 0) {
      return res.status(409).json({ error: "Order is already fully refunded" });
    }
    if (amountCents !== undefined && amountCents > refundable) {
      return res.status(400).json({
        error: `Amount exceeds refundable balance (${refundable} cents)`,
      });
    }

    // --- Call the provider ---
    const result = await refundOrder({
      orderId: order.id,
      paymentIntentId: order.paymentIntentId,
      amountCents,
      reason,
      adminUserId: req.user.id,
      idempotencyKey: `refund:${order.id}:${requestId}`,
    });

    // --- Audit trail (log failures too) ---
    await db.refundAudit.insert({
      orderId: order.id,
      adminUserId: req.user.id,
      amountCents: amountCents ?? refundable,
      reason: reason ?? null,
      requestId,
      ok: result.ok,
      stripeRefundId: result.ok ? result.refundId : null,
      errorCode: result.ok ? null : result.code ?? null,
    });

    if (!result.ok) {
      return res.status(422).json({ error: result.message, code: result.code });
    }

    // Mark pending; the webhook is the source of truth for the final state.
    await db.orders.update(order.id, { refundStatus: "pending" });

    return res.status(202).json({
      refundId: result.refundId,
      status: result.status,
    });
  }
);

export default router;
```

I return `202` rather than `200` because the refund may not be settled yet. Your `refund.updated` / `charge.refunded` webhook should update `refundedCents` and the final status.

