  const requestId = useRef<string>("");

  function openDialog() {
    requestId.current = crypto.randomUUID(); // one ID per dialog session
    setError(null);
    setOpen(true);
  }

  async function submit() {
    if (submitting) return;
    setSubmitting(true);
    setError(null);

    try {
      const res = await fetch(`/admin/orders/${orderId}/refund`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          amountCents: amount ? Math.round(parseFloat(amount) * 100) : undefined,
          reason,
          requestId: requestId.current,
        }),
      });

      const data = await res.json().catch(() => ({}));

      if (!res.ok) {
        // Definite rejection: use a fresh ID if the admin edits and retries
        requestId.current = crypto.randomUUID();
        setError(data.error ?? "Refund failed");
        return;
      }

      setOpen(false);
      onDone(); // refetch the order
    } catch {
      // Network error: outcome unknown. Keep the SAME requestId so a retry
      // can't double-refund.
      setError("Network error. It's safe to try again, but check the order first.");
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <>
      <button onClick={openDialog} disabled={refundableCents <= 0}>
