```ts
export interface Ingredient {
  name: string;
  quantity: number | null; // null for things like "salt, to taste"
  unit?: string | null;    // "cup", "g", "clove", or none for countable items
}

type Dimension = "volume" | "mass";

// factor = how many base units (ml for volume, g for mass) in one of this unit
const UNITS: Record<string, { dimension: Dimension; factor: number }> = {
  ml:   { dimension: "volume", factor: 1 },
  l:    { dimension: "volume", factor: 1000 },
  tsp:  { dimension: "volume", factor: 4.92892 },
  tbsp: { dimension: "volume", factor: 14.7868 },
  floz: { dimension: "volume", factor: 29.5735 },
  cup:  { dimension: "volume", factor: 236.588 },
  g:    { dimension: "mass", factor: 1 },
  kg:   { dimension: "mass", factor: 1000 },
  oz:   { dimension: "mass", factor: 28.3495 },
  lb:   { dimension: "mass", factor: 453.592 },
};

const UNIT_ALIASES: Record<string, string> = {
  milliliter: "ml", milliliters: "ml", millilitre: "ml", millilitres: "ml",
  liter: "l", liters: "l", litre: "l", litres: "l",
  teaspoon: "tsp", teaspoons: "tsp", tsps: "tsp",
  tablespoon: "tbsp", tablespoons: "tbsp", tbsps: "tbsp",
  "fl oz": "floz", "fluid ounce": "floz", "fluid ounces": "floz",
  cups: "cup",
  gram: "g", grams: "g",
  kilogram: "kg", kilograms: "kg",
  ounce: "oz", ounces: "oz",
  pound: "lb", pounds: "lb", lbs: "lb",
};

const NO_SINGULARIZE = new Set(["hummus", "asparagus", "molasses", "couscous", "swiss"]);

function normalizeUnit(unit?: string | null): string {
  const u = (unit ?? "").trim().toLowerCase().replace(/\.$/, "");
  return UNIT_ALIASES[u] ?? u;
}

function normalizeName(name: string): string {
  const n = name.trim().toLowerCase().replace(/\s+/g, " ");
  if (NO_SINGULARIZE.has(n)) return n;
  if (n.endsWith("ies")) return n.slice(0, -3) + "y";          // berries -> berry
  if (n.endsWith("oes")) return n.slice(0, -2);                // tomatoes -> tomato
  if (n.endsWith("s") && !n.endsWith("ss")) return n.slice(0, -1);
  return n;
}

export function mergeIngredients(ingredients: Ingredient[]): Ingredient[] {
  const merged = new Map<string, { name: string; unit: string; quantity: number | null }>();

  for (const ing of ingredients) {
    const name = normalizeName(ing.name);
    const unit = normalizeUnit(ing.unit);
    const def = UNITS[unit];

    // Convertible units merge by dimension; anything else ("clove", "can", "")
    // only merges with the exact same unit.
    const key = `${name}|${def ? def.dimension : `unit:${unit}`}`;
    const existing = merged.get(key);

    if (!existing) {
      merged.set(key, { name, unit, quantity: ing.quantity });
      continue;
    }

    if (ing.quantity == null) continue; // "to taste" adds nothing to an existing amount

    // Convert into the unit of the first occurrence
    const converted = def
      ? (ing.quantity * def.factor) / UNITS[existing.unit].factor
      : ing.quantity;

    existing.quantity = (existing.quantity ?? 0) + converted;
  }

  return [...merged.values()].map(({ name, unit, quantity }) => ({
    name,
    unit: unit || null,
    quantity: quantity == null ? null : Math.round(quantity * 100) / 100,
  }));
}
```

Example:

```ts
mergeIngredients([
  { name: "Tomatoes", quantity: 2, unit: null },
  { name: "tomato", quantity: 3, unit: null },
  { name: "flour", quantity: 1, unit: "cup" },
  { name: "Flour", quantity: 120, unit: "g" },     // different dimension, stays separate
  { name: "olive oil", quantity: 2, unit: "tbsp" },
  { name: "olive oil", quantity: 1, unit: "tsp" },
]);
// → tomato 5, flour 1 cup, flour 120 g, olive oil 2.33 tbsp
```

Some behaviors to be aware of:

- **Volume and mass don't merge.** "1 cup flour" and "120 g flour" stay as two lines, since converting would need per-ingredient densities. That's a possible later improvement.
- **Output unit is the first one seen.** The olive oil above comes out as 2.33 tbsp rather than something friendlier. If you want nicer display (e.g. 7 tsp → 2 tbsp + 1 tsp), that would be a separate formatting step.
- **Singularization is naive.** I used a simple plural-stripper with a small exception list. If you have an ingredient database or IDs, key on those instead of names. That will be more reliable than string matching.
- **Countable units only merge on exact match.** "2 cloves garlic" and "1 clove garlic" merge only if the unit is normalized the same way. You may want to add "cloves" → "clove" aliases.

