import express, { Request, Response, NextFunction } from "express";
import { mergeIngredients, Ingredient } from "./mergeIngredients";
import { requireAuth } from "./auth";
import { getSavedRecipesForWeek } from "./recipeRepo";

// Assumed repo signature:
// getSavedRecipesForWeek(userId: string, start: Date, end: Date)
//   => Promise<{ id: string; title: string; ingredients: Ingredient[] }[]>

const router = express.Router();

// Parses "YYYY-MM-DD". Defaults to Monday of the current week (UTC).
function parseWeekStart(raw: unknown): Date | null {
  if (raw === undefined) {
    const d = new Date();
    d.setUTCHours(0, 0, 0, 0);
    const daysSinceMonday = (d.getUTCDay() + 6) % 7;
    d.setUTCDate(d.getUTCDate() - daysSinceMonday);
    return d;
  }
  if (typeof raw !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(raw)) return null;
  const d = new Date(`${raw}T00:00:00Z`);
  return Number.isNaN(d.getTime()) ? null : d;
}

// GET /api/shopping-list?weekStart=2025-01-06
router.get(
  "/api/shopping-list",
  requireAuth,
  async (req: Request, res: Response, next: NextFunction) => {
    try {
      const weekStart = parseWeekStart(req.query.weekStart);
      if (!weekStart) {
        return res
          .status(400)
          .json({ error: "weekStart must be a date in YYYY-MM-DD format" });
      }

      const weekEnd = new Date(weekStart);
      weekEnd.setUTCDate(weekEnd.getUTCDate() + 7);

      const recipes = await getSavedRecipesForWeek(req.user!.id, weekStart, weekEnd);

      const items = mergeIngredients(recipes.flatMap((r) => r.ingredients)).sort(
        (a, b) => a.name.localeCompare(b.name)
      );

      res.json({
        weekStart: weekStart.toISOString().slice(0, 10),
        recipes: recipes.map(({ id, title }) => ({ id, title })),
        items,
      });
    } catch (err) {
      next(err);
    }
  }
);

export default router;
