type Family = "volume" | "weight";

// factor converts to a base unit: ml for volume, g for weight
const UNITS: Record<string, { family: Family; factor: number }> = {
  tsp: { family: "volume", factor: 4.92892 },
  tbsp: { family: "volume", factor: 14.7868 },
  cup: { family: "volume", factor: 236.588 },
  "fl oz": { family: "volume", factor: 29.5735 },
  ml: { family: "volume", factor: 1 },
  l: { family: "volume", factor: 1000 },
  g: { family: "weight", factor: 1 },
  kg: { family: "weight", factor: 1000 },
  oz: { family: "weight", factor: 28.3495 },
  lb: { family: "weight", factor: 453.592 },
};

const UNIT_ALIASES: Record<string, string> = {
  teaspoon: "tsp", teaspoons: "tsp", tsps: "tsp",
  tablespoon: "tbsp", tablespoons: "tbsp", tbsps: "tbsp",
  cups: "cup", c: "cup",
  "fluid ounce": "fl oz", "fluid ounces": "fl oz",
  milliliter: "ml", milliliters: "ml",
  liter: "l", liters: "l", litre: "l", litres: "l",
  gram: "g", grams: "g",
  kilogram: "kg", kilograms: "kg",
  ounce: "oz", ounces: "oz",
  pound: "lb", pounds: "lb", lbs: "lb",
};

const SINGULAR_EXCEPTIONS = new Set(["hummus", "molasses", "asparagus", "couscous"]);

function normalizeName(name: string): string {
  const n = name.toLowerCase().trim().replace(/\s+/g, " ");
  if (SINGULAR_EXCEPTIONS.has(n)) return n;
  if (n.endsWith("ies")) return n.slice(0, -3) + "y";
  if (n.endsWith("ss") || n.endsWith("us")) return n;
  if (n.endsWith("s")) return n.slice(0, -1);
  return n;
}

function normalizeUnit(unit: string | null): string | null {
  if (!unit) return null;
  const u = unit.toLowerCase().trim().replace(/\.$/, "");
  return UNIT_ALIASES[u] ?? u;
}

interface Accumulator {
  name: string;
  unit: string | null;      // display unit
  baseTotal: number;        // in base units if convertible, else raw
  factor: number;           // display unit -> base
  hasQuantity: boolean;
}

export function mergeIngredients(ingredients: Ingredient[]): Ingredient[] {
  const merged = new Map<string, Accumulator>();

  for (const item of ingredients) {
    const name = normalizeName(item.name);
    const unit = normalizeUnit(item.unit);
    const info = unit ? UNITS[unit] : undefined;

    // Items only merge if their units are compatible:
    // same family (volume/weight), same unknown unit ("clove"), or both unitless.
    const bucket = info ? info.family : unit ? `other:${unit}` : "count";
    const key = `${name}|${bucket}`;

    let acc = merged.get(key);
    if (!acc) {
      acc = {
        name: item.name.trim(),
        unit,
        baseTotal: 0,
        factor: info?.factor ?? 1,
        hasQuantity: false,
      };
      merged.set(key, acc);
    }

    if (item.quantity != null) {
      acc.baseTotal += item.quantity * (info?.factor ?? 1);
      acc.hasQuantity = true;
    }
  }

  return [...merged.values()].map((acc) => ({
    name: acc.name,
    unit: acc.unit,
    quantity: acc.hasQuantity
      ? Math.round((acc.baseTotal / acc.factor) * 100) / 100
      : null,
  }));
}
```

Example:

```typescript
mergeIngredients([
  { name: "Flour", quantity: 1, unit: "cup" },
  { name: "flour", quantity: 120, unit: "ml" },
  { name: "Eggs", quantity: 2, unit: null },
  { name: "egg", quantity: 1, unit: null },
  { name: "Salt", quantity: null, unit: null },
  { name: "salt", quantity: 1, unit: "tsp" },
]);
// → flour 1.51 cup, eggs 3, salt 1 tsp (plus a separate unitless "Salt")
```

Behaviors you may want to change:

- **Volume and weight don't merge.** "1 cup flour" and "200 g flour" stay as separate lines, since converting would need per-ingredient densities. That's usually the right call for a v1.
- **The first-seen unit is the display unit.** Adding 1 tbsp and 1 cup gives 17 tbsp. A "prettify" step could pick the most readable unit, such as 1 cup + 1 tbsp.
- **Plural handling is naive.** The singularizer plus the exceptions list covers common cases, but you'll probably need to extend it or use a proper library.
- **Unitless and unit entries stay separate.** "1 onion" and "1 cup onion, diced" become two lines, and "salt to taste" doesn't fold into "1 tsp salt".
- **Preparation notes aren't handled.** "Onion, diced" and "onion, sliced" only merge if you strip the notes into a separate field first.

