// Pass in rows from the batches table:
// [{ batch_number: "B-0142", brew_date: "2025-03-18" }, ...]
function formatBrewDate(value) {
  // Parse as a local date to avoid timezone shifting "YYYY-MM-DD" back a day
  const [y, m, d] = String(value).slice(0, 10).split("-").map(Number);
  return new Date(y, m - 1, d).toLocaleDateString("en-GB", {
    day: "2-digit", month: "short", year: "numeric"
  }); // e.g. 18 Mar 2025
}

function renderLabels(batches, copiesPerBatch = 1) {
  const container = document.getElementById("labels");
  container.innerHTML = "";

  for (const batch of batches) {
    for (let i = 0; i < copiesPerBatch; i++) {
      const el = document.createElement("div");
      el.className = "label";

      const top = document.createElement("div");
      const topLabel = document.createElement("p");
      topLabel.className = "field-label";
      topLabel.textContent = "Batch";
      const number = document.createElement("p");
      number.className = "batch-number";
      number.textContent = batch.batch_number;
      top.append(topLabel, number);

      const bottom = document.createElement("div");
      bottom.className = "row";
      const dateLabel = document.createElement("p");
      dateLabel.className = "field-label";
      dateLabel.textContent = "Brewed";
      const date = document.createElement("p");
      date.className = "brew-date";
      date.textContent = formatBrewDate(batch.brew_date);
      bottom.append(dateLabel, date);

      el.append(top, bottom);
      container.appendChild(el);
    }
  }
}
