**routes/labels.js**
```js
const express = require("express");
const db = require("../db"); // your pg Pool

const router = express.Router();

// GET /batches/:id/label?copies=2
router.get("/batches/:id/label", async (req, res, next) => {
  try {
    const id = Number(req.params.id);
    if (!Number.isInteger(id) || id < 1) {
      return res.status(400).send("Invalid batch id");
    }

    const copies = req.query.copies === undefined ? 1 : Number(req.query.copies);
    if (!Number.isInteger(copies) || copies < 1 || copies > 100) {
      return res.status(400).send("copies must be a whole number from 1 to 100");
    }

    // to_char keeps brew_date as a plain 'YYYY-MM-DD' string. Without it, pg
    // returns a JS Date, which JSON-serialises as UTC and can shift the date
    // by a day.
    const { rows } = await db.query(
      `SELECT batch_number,
              to_char(brew_date, 'YYYY-MM-DD') AS brew_date
         FROM batches
        WHERE id = $1`,
      [id]
    );

    if (rows.length === 0) {
      return res.status(404).send("Batch not found");
    }

    // Escape "<" so batch data can never close the script tag early
    const payload = JSON.stringify({ batches: rows, copies }).replace(/</g, "\\u003c");

    res.type("html").send(`<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <title>Batch Label</title>
  <link rel="stylesheet" href="/label-assets/label.css">
</head>
<body>
  <div id="labels"></div>
  <script type="application/json" id="label-data">${payload}</script>
  <script src="/label-assets/labels.js"></script>
  <script>
    const { batches, copies } = JSON.parse(
      document.getElementById("label-data").textContent
    );
    renderLabels(batches, copies);
    window.addEventListener("load", () => window.print());
  </script>
</body>
</html>`);
  } catch (err) {
    next(err);
  }
});

module.exports = router;
```

