Your ride record's schema wasn't specified, so I assumed a shape and wrote this in TypeScript. Adjust the field names to match your real model.

```ts
interface RideRecord {
  id: string;
  userEmail: string;
  scooterId: string;
  startedAt: Date;
  endedAt: Date | null;
  distanceMeters?: number;
  currency: string;               // ISO 4217, e.g. "USD"
  pricing: {                      // snapshot of the rates applied to this ride
    unlockFeeCents: number;
    perMinuteCents: number;
  };
  discountCents?: number;
  taxRate?: number;               // e.g. 0.08 for 8%
}

interface ReceiptLineItem {
  description: string;
  amountCents: number;
}

interface Receipt {
  receiptNumber: string;
  rideId: string;
  to: string;
  currency: string;
  startedAt: Date;
  endedAt: Date;
  durationMinutes: number;        // billable minutes (rounded up)
  distanceKm?: number;
  lineItems: ReceiptLineItem[];
  subtotalCents: number;
  taxCents: number;
  totalCents: number;
}

export function buildReceipt(ride: RideRecord): Receipt {
  if (!ride.endedAt) {
    throw new Error(`Cannot build receipt: ride ${ride.id} has not ended`);
  }

  const durationMs = ride.endedAt.getTime() - ride.startedAt.getTime();
  if (durationMs < 0) {
    throw new Error(`Ride ${ride.id} has endedAt before startedAt`);
  }

  // Bill per started minute; adjust if your pricing rounds differently.
  const billableMinutes = Math.max(1, Math.ceil(durationMs / 60_000));

  const lineItems: ReceiptLineItem[] = [
    { description: "Unlock fee", amountCents: ride.pricing.unlockFeeCents },
    {
      description: `Ride time (${billableMinutes} min × ${formatMoney(ride.pricing.perMinuteCents, ride.currency)}/min)`,
      amountCents: billableMinutes * ride.pricing.perMinuteCents,
    },
  ];

  if (ride.discountCents && ride.discountCents > 0) {
    lineItems.push({ description: "Discount", amountCents: -ride.discountCents });
  }

  const subtotalCents = Math.max(
    0,
    lineItems.reduce((sum, item) => sum + item.amountCents, 0)
  );
  const taxCents = Math.round(subtotalCents * (ride.taxRate ?? 0));

  return {
    receiptNumber: `R-${ride.id}`,
    rideId: ride.id,
    to: ride.userEmail,
    currency: ride.currency,
    startedAt: ride.startedAt,
    endedAt: ride.endedAt,
    durationMinutes: billableMinutes,
    distanceKm:
      ride.distanceMeters != null
        ? Math.round(ride.distanceMeters / 10) / 100
        : undefined,
    lineItems,
    subtotalCents,
    taxCents,
    totalCents: subtotalCents + taxCents,
  };
}

export function formatMoney(cents: number, currency: string): string {
  return new Intl.NumberFormat("en-US", { style: "currency", currency }).format(cents / 100);
}
```

Some choices to check:

- **Money is in integer cents** to avoid floating-point errors. Only `formatMoney` converts to a display value.
- **It throws if the ride hasn't ended**, so a bad trigger can't send a half-complete receipt.
- **It uses the pricing snapshot stored on the ride**, not current rates, so later price changes don't alter old receipts.
- **The receipt total should match what the customer was actually charged.** If you have a payment or charge record, build the totals from that instead of recomputing, or at least assert that the two agree. Otherwise a rounding or promo-logic difference will produce a receipt that doesn't match the card statement.
- **Receipt number:** `R-${ride.id}` is a placeholder. Use your own sequence if you need one for accounting.

