This builds on the `Receipt` type from before and returns the subject, HTML, and plain text together, so you can pass them straight to your email provider (most want both parts).

```ts
import { Receipt, formatMoney } from "./receipt";

interface RenderOptions {
  brandName: string;
  supportEmail: string;
  timeZone?: string; // IANA zone, e.g. "America/Chicago"
  locale?: string;   // defaults to "en-US"
}

export interface RenderedEmail {
  subject: string;
  html: string;
  text: string;
}

const escapeHtml = (s: string): string =>
  s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");

function formatDateTime(d: Date, opts: RenderOptions): string {
  return new Intl.DateTimeFormat(opts.locale ?? "en-US", {
    dateStyle: "medium",
    timeStyle: "short",
    timeZone: opts.timeZone, // undefined falls back to the server's zone
    timeZoneName: "short",
  }).format(d);
}

export function renderReceipt(receipt: Receipt, opts: RenderOptions): RenderedEmail {
  const money = (cents: number) => formatMoney(cents, receipt.currency);
  const started = formatDateTime(receipt.startedAt, opts);
  const ended = formatDateTime(receipt.endedAt, opts);

  const subject = `Your ${opts.brandName} receipt: ${money(receipt.totalCents)}`;

  // ---------- Plain text ----------
  const textLines = [
    `${opts.brandName} receipt`,
    `Receipt ${receipt.receiptNumber}`,
    "",
    `Start: ${started}`,
    `End:   ${ended}`,
    `Duration: ${receipt.durationMinutes} min`,
    ...(receipt.distanceKm != null ? [`Distance: ${receipt.distanceKm} km`] : []),
    "",
    ...receipt.lineItems.map((i) => `${i.description}: ${money(i.amountCents)}`),
    "",
    `Subtotal: ${money(receipt.subtotalCents)}`,
    ...(receipt.taxCents > 0 ? [`Tax: ${money(receipt.taxCents)}`] : []),
    `Total: ${money(receipt.totalCents)}`,
    "",
    `Questions? Contact ${opts.supportEmail}`,
  ];
  const text = textLines.join("\n");

  // ---------- HTML ----------
  const row = (label: string, value: string, bold = false) => `
        <tr>
          <td style="padding:6px 0;${bold ? "font-weight:bold;" : ""}">${escapeHtml(label)}</td>
          <td style="padding:6px 0;text-align:right;${bold ? "font-weight:bold;" : ""}">${escapeHtml(value)}</td>
        </tr>`;

  const itemRows = receipt.lineItems
    .map((i) => row(i.description, money(i.amountCents)))
    .join("");

  const html = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(subject)}</title>
</head>
<body style="margin:0;padding:0;background:#f4f4f5;font-family:-apple-system,Segoe UI,Helvetica,Arial,sans-serif;color:#111827;">
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f4f5;padding:24px 0;">
    <tr>
      <td align="center">
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border-radius:8px;padding:32px;">
          <tr>
            <td>
              <h1 style="margin:0 0 4px;font-size:20px;">${escapeHtml(opts.brandName)}</h1>
              <p style="margin:0 0 24px;color:#6b7280;font-size:14px;">Receipt ${escapeHtml(receipt.receiptNumber)}</p>

              <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="font-size:14px;margin-bottom:24px;">
                ${row("Start", started)}
                ${row("End", ended)}
                ${row("Duration", `${receipt.durationMinutes} min`)}
                ${receipt.distanceKm != null ? row("Distance", `${receipt.distanceKm} km`) : ""}
              </table>

              <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="font-size:14px;border-top:1px solid #e5e7eb;">
                ${itemRows}
              </table>

              <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="font-size:14px;border-top:1px solid #e5e7eb;margin-top:8px;">
                ${row("Subtotal", money(receipt.subtotalCents))}
                ${receipt.taxCents > 0 ? row("Tax", money(receipt.taxCents)) : ""}
                ${row("Total", money(receipt.totalCents), true)}
              </table>

              <p style="margin:24px 0 0;color:#6b7280;font-size:12px;">
                Questions about this charge? Contact
                <a href="mailto:${escapeHtml(opts.supportEmail)}" style="color:#6b7280;">${escapeHtml(opts.supportEmail)}</a>.
              </p>
            </td>
          </tr>
        </table>
      </td>
    </tr>
  </table>
</body>
</html>`;

  return { subject, html, text };
}
```

Notes:

- **Layout is table-based with inline styles.** Many email clients, Outlook especially, ignore or strip `<style>` blocks and modern CSS layout. It is deliberately plain.
- **All dynamic values are HTML-escaped**, including line item descriptions, so nothing odd in the data can break the markup.
- **Time zone:** the `Receipt` doesn't carry one. If you don't pass `timeZone`, times render in the server's zone (often UTC), which can confuse riders. Ideally pass the zone of the city where the ride happened, or the user's profile zone. Including the zone abbreviation, as this does, at least keeps it unambiguous.
- **Tax and distance rows only appear when relevant**, so rides with no tax don't show a "Tax: $0.00" line.
- **Locale:** `formatMoney` from earlier is hardcoded to `en-US`. If you localize, thread `locale` through it as well.
- **Things you'll likely add:** a logo, a route map image, and a payment-method line such as "Visa ending 4242". The last one needs data from your payment record, which ties back to making the receipt total come from the actual charge.

